import { test, expect } from '@playwright/test';
import { readFile } from 'node:fs/promises';

test('exported architecture runs its real ONNX WASM interface without claiming learned accuracy', async ({ page }) => {
  test.setTimeout(120_000);
  // Opt-in training-tool integration; generated by tools/reference-analysis/verify-model.py.
  // Diagnostic random weights are never passed through the release manifest gate.
  const bytes = await readFile(new URL('../../build-native/reference-analysis/interface-smoke.onnx', import.meta.url));
  await page.route('**/reference-interface.onnx', route => route.fulfill({ contentType: 'application/octet-stream', body: bytes }));
  await page.route('**/reference-interface-harness', route => route.fulfill({ contentType: 'text/html', body: '<!doctype html><title>ONNX interface diagnostic</title>' }));
  const external = [];
  page.on('request', request => { if (/^https?:/.test(request.url()) && !request.url().startsWith('http://127.0.0.1:')) external.push(request.url()); });
  await page.goto('/reference-interface-harness');
  const result = await page.evaluate(async () => {
    const ort = await import('/assets/vendor/reference-analysis/ort.wasm.min.mjs');
    ort.env.wasm.wasmPaths = new URL('/assets/vendor/reference-analysis/', globalThis.location.href).href;
    ort.env.wasm.numThreads = 1;
    const session = await ort.InferenceSession.create(await (await globalThis.fetch('/reference-interface.onnx')).arrayBuffer(), { executionProviders: ['wasm'] });
    const inputs = { tile: new ort.Tensor('float32', new Float32Array(3 * 512 * 512), [1, 3, 512, 512]),
      overview: new ort.Tensor('float32', new Float32Array(3 * 256 * 256), [1, 3, 256, 256]),
      position: new ort.Tensor('float32', Float32Array.from([0, 0, 1, 1]), [1, 4]) };
    let output;
    try {
      output = await session.run(inputs);
      return { dimensions: output.logits.dims, finite: output.logits.data.every(Number.isFinite) };
    } finally {
      for (const tensor of Object.values(inputs)) tensor.dispose();
      for (const tensor of Object.values(output || {})) tensor.dispose();
      await session.release();
    }
  });
  expect(result.dimensions).toEqual([1, 7, 512, 512]);
  expect(result.finite).toBe(true);
  expect(external).toEqual([]);
});
